const SPHINX = "sphinx";
const BASE_SCORE = 1;
const FREE_TYPE_ALLOWANCE = 3;
const MINIMUM_BONUS = 1;
const BONUS_PER_EXTRA_TYPE = 2;

const countDistinctTypes = (army: Card[]): number =>
  new Set(army.map((card) => card.monster)).size;

const bonusForOtherTypes = (otherTypes: number): number =>
  otherTypes > FREE_TYPE_ALLOWANCE
    ? BONUS_PER_EXTRA_TYPE * (otherTypes - FREE_TYPE_ALLOWANCE)
    : MINIMUM_BONUS;

export const scoreArmy = (army: Card[]): number => {
  const hasSphinx = army.some((card) => card.monster === SPHINX);
  if (!hasSphinx) return 0;

  const otherTypes = countDistinctTypes(army) - 1;
  return BASE_SCORE + bonusForOtherTypes(otherTypes);
};
